node -e 'const fs = require("fs")
const d = "supabase/migrations"
let last = null
for (const f of fs.readdirSync(d).filter((x) => x.endsWith(".sql")).sort()) {
  const s = fs.readFileSync(d + "/" + f, "utf8")
  const re = /create\s+policy\s+"[^"]*"\s+on\s+public\.circle_channels\s+for\s+select[\s\S]*?;/gi
  let m
  while ((m = re.exec(s)) !== null) last = m[0]
}
if (last === null) { console.error("probe could not look: no select policy on circle_channels"); process.exit(79) }
if (/using\s*\(\s*true\s*\)/i.test(last)) { console.error("SCAN-651: circle_channels is readable by anon with using (true), so anyone with the anon key lists the ids of unlisted, closed Circles (ADR-1015) and the Channels they carry."); process.exit(1) }
'
